                }
              } else if (f === 'title' && !row.productId) {
                var idm = String(txt).match(/\b(\d{6,})\b/);
                if (idm) row.productId = idm[1];
              }
            }
          } else {
            row[f] = parseNumber(txt);
          }
        }
        if (
          row.productId ||
