                  if (pm) row.productId = pm[1];
                }
              } else if (f === 'title' && !row.productId) {
                var idm = String(txt).match(/\b(\d{6,})\b/);
                if (idm) row.productId = idm[1];
              }
            }
          } else {
            row[f] = parseNumber(txt);
          }
        }
        if (
          row.productId ||
          row.title ||
          row.impressions != null ||
          row.clicks != null ||
          row.ctr != null ||
          row.gmv != null
        ) {
          items.push(row);
        }
      }
      if (items.length > best.length) {
        best = items;
        bestHeaders = headers;
      }
    }
    return { products: best, headers: bestHeaders };
  }

