async def _tk_data_freshness(db: AsyncSession) -> dict[str, Any]:
    """各事实表最新 biz_date + 陈旧标记（任务台总览 / 质量可观测）。"""
    today = date.today()
    row = (
        await db.execute(
            text(
                """
                SELECT
                  (SELECT MAX(biz_date) FROM tk.fact_tiktok_shop_daily) AS shop_daily_max,
                  (SELECT MAX(biz_date) FROM tk.fact_ads_campaign_daily
                    WHERE campaign_name !~ '^【') AS ads_max,
                  (SELECT MAX(biz_date) FROM tk.fact_tiktok_content_daily) AS content_max,
                  (SELECT MAX(biz_date) FROM tk.fact_tiktok_product_traffic_daily) AS traffic_max,
                  (SELECT COUNT(*)::int FROM tk.fact_tk_anomaly_task
                    WHERE status IN ('open', 'in_progress')) AS open_anomaly_count,
                  (SELECT COUNT(*)::int FROM tk.fact_tk_anomaly_task
                    WHERE status IN ('open', 'in_progress')
                      AND COALESCE(needs_boss_decision, FALSE)) AS boss_decision_count
                """
            )
        )
    ).mappings().first() or {}

    def _age(d: Any) -> int | None:
        if d is None:
            return None
        if hasattr(d, "isoformat"):
            return (today - d).days
        try:
            return (today - date.fromisoformat(str(d)[:10])).days
        except ValueError:
            return None

    shop_max = row.get("shop_daily_max")
    ads_max = row.get("ads_max")
    content_max = row.get("content_max")
    traffic_max = row.get("traffic_max")
    shop_age = _age(shop_max)
    ads_age = _age(ads_max)
    content_age = _age(content_max)
    traffic_age = _age(traffic_max)

    # 阈值与 scripts/tk_daily_quality_check.py 对齐：店日>2 天 warn；广告>3 天 warn
    stale: list[str] = []
    if shop_max is None:
        stale.append("shop_daily_empty")
    elif shop_age is not None and shop_age > 2:
        stale.append("shop_daily")
    if ads_max is None:
        stale.append("ads_empty")
    elif ads_age is not None and ads_age > 3:
        stale.append("ads")
    if content_max is None:
        stale.append("content_empty")
    elif content_age is not None and content_age > 7:
        stale.append("content")
    if traffic_max is None:
        stale.append("traffic_empty")
    elif traffic_age is not None and traffic_age > 7:
        stale.append("traffic")

    return {
        "as_of": today.isoformat(),
        "shop_daily_max": _iso(shop_max),
        "ads_max": _iso(ads_max),
        "content_max": _iso(content_max),
        "traffic_max": _iso(traffic_max),
        "shop_daily_age_days": shop_age,
        "ads_age_days": ads_age,
        "content_age_days": content_age,
        "traffic_age_days": traffic_age,
        "open_anomaly_count": int(row.get("open_anomaly_count") or 0),
        "boss_decision_count": int(row.get("boss_decision_count") or 0),
        "stale": stale,
        "ok": len(stale) == 0,
    }


